 return mix(d1, d2, blendFactor);
}
Noise-Based Blending:
Blend two shapes using a 3D noise function to create organic and complex boundaries between them.
glsl
Copy code
float noiseBlendSDF(vec3 p, float d1, float d2, float noiseScale) {
 float noiseValue = (cnoise(p \* noiseScale) + 1.0) \* 0.5;
 return mix(d1, d2, noiseValue);
