Directional Blend:
Create a blend between two shapes based on the direction of a specified axis. This can be useful for creating interesting patterns along a specific direction.
glsl
Copy code
float directionalBlendSDF(vec3 p, float d1, float d2, vec3 axis) {
 float axisValue = dot(p, normalize(axis));
 float blendFactor = smoothstep(-1.0, 1.0, axisValue);
 return mix(d1, d2, blendFactor);
}
Radial Blend:
Blend two shapes based on their distance from a given center point. This can be used to create interesting radial patterns and transitions.
glsl
Copy code
float radialBlendSDF(vec3 p, float d1, float d2, vec3 center, float radius) {
 float distanceFromCenter = length(p - center);
 float blendFactor = smoothstep(radius, radius \* 1.1, distanceFromCenter);
 return mix(d1, d2, blendFactor);
}
